struct LzqRoot { ze_device_handle_t h; uint32_t driver; ze_device_uuid_t uuid; uint32_t vendor; uint32_t device; ze_device_type_t type; uint32_t subdeviceId; char name[ZE_MAX_DEVICE_NAME]; uint32_t first_node; uint32_t alias_count; bool ext_known; ze_result_t ext_r; uint64_t mem_import; uint64_t mem_export; uint64_t img_import; uint64_t img_export; bool q_known; ze_result_t q_r; uint32_t q_count; uint32_t q_queues[LZQ_MAX_QG]; uint64_t q_flags[LZQ_MAX_QG]; bool q_truncated; };
